def difference_update(self, *others):
    "difference_update(*others) -> discard elements found in any other"
    for other in others:
        if other is self:
            self.clear()
        else:
            # Membership checks must not repeatedly consume an iterator.
            if not hasattr(other, '__contains__'):
                other = set(other)
            for val in self.intersection(other):
                self.discard(val)
